refentry.refsect1:
&reftitle.description;
public voidIo\Poll\Watcher::modify arrayevents mixeddata&null;
Replaces the watched events, as Io\Poll\Watcher::modifyEvents does, and replaces the associated data if data is passed.

  &reftitle.examples;

   Io\Poll\Watcher::modify example


<?php
use Io\Poll\Context;
use Io\Poll\Event;
use Time\Duration;

[$reader, $writer] = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);

$context = new Context();
$watcher = $context->add(new StreamPollHandle($writer), [Event::Read], 'waiting for a reply');

$watcher->modify([Event::Write], 'ready to send');

foreach ($context->wait(Duration::fromSeconds(1)) as $watcher) {
    echo $watcher->getData(), PHP_EOL;
    var_dump($watcher->getTriggeredEvents());
}


   &example.outputs;


ready to send
array(1) {
  [0]=>
  enum(Io\Poll\Event::Write)
}
